  'settings.magicPrompts.page.group.sessionSummary.description': 'Prompty używane przez polecenie /summary: widoczna wiadomość użytkownika + ukryte instrukcje. Niedestrukcyjne – nie kompaktuje historii sesji.',
  'settings.magicPrompts.page.group.sessionSummary.title': 'Podsumowanie Sesji',
  'settings.magicPrompts.page.group.sessionWorkspaceReview.description': 'Prompty używane przez polecenie /workspace-review: widoczna wiadomość użytkownika + ukryte instrukcje. Sprawdza diff obszaru roboczego — czy realizuje swój zamiar oraz czy jest poprawny i adekwatny, klasyfikując znaleziska według wagi.',
  'settings.magicPrompts.page.group.sessionFeaturePlan.title': 'Planowanie funkcji',
  'settings.magicPrompts.page.group.sessionFeaturePlan.description': 'Prompty używane przez polecenie /plan-feature: widoczna wiadomość użytkownika + ukryte instrukcje. Uruchamia prowadzony dialog, który bada kod i zadaje pytania doprecyzowujące w małych partiach przed utworzeniem planu implementacji.',
  'settings.magicPrompts.page.group.sessionCatchUp.title': 'Nadrobienie kontekstu',
  'settings.magicPrompts.page.group.sessionCatchUp.description': 'Prompty używane przez polecenie /catch-up: widoczna wiadomość użytkownika + ukryte instrukcje. Buduje kontekst zależny od gałęzi — commity gałęzi, jej PR i niezatwierdzone zmiany razem — aby zrozumieć, nad czym pracowałeś, a następnie daje przystępne podsumowanie i produktowy następny krok.',
  'settings.magicPrompts.page.group.sessionDebug.title': 'Debugowanie',
  'settings.magicPrompts.page.group.sessionDebug.description': 'Prompty używane przez polecenie /debug: widoczna wiadomość użytkownika + ukryte instrukcje. Prowadzi badanie pierwotnej przyczyny — rejestruje objaw, formułuje hipotezy, sprawdza je w kodzie i potwierdza przyczynę przed zaproponowaniem poprawki.',
  'settings.magicPrompts.page.group.sessionWeigh.title': 'Rozważanie opcji',
  'settings.magicPrompts.page.group.sessionWeigh.description': 'Prompty używane przez polecenie /weigh: widoczna wiadomość użytkownika + ukryte instrukcje. Bada kod, a następnie przedstawia 2-3 różne podejścia z kompromisami i rekomendacją — bez pisania planu ani kodu.',
  'settings.magicPrompts.page.group.sessionWorkspaceReview.title': 'Przegląd obszaru roboczego',
  'settings.magicPrompts.page.group.sessionExplore.title': 'Przegląd bazy kodu',
  'settings.magicPrompts.page.group.sessionExplore.description': 'Prompty używane przez polecenie /explore: widoczna wiadomość użytkownika + ukryte instrukcje. Bada repozytorium i daje uporządkowaną orientację — ogólny obraz, główne moduły, jak się łączą i od czego zacząć — zamiast zrzutu plik po pliku.',
