  "settings.varin.pluginSettings.webAccess.providers.firecrawlRisk": "Świeże zeskrobanie umożliwia serwerowi Firecrawl wysyłanie żądań wychodzących. Włącz tę opcję tylko wtedy, gdy to wdrożenie ma odpowiednią izolację sieci.",
