  "settings.varin.pluginSettings.webAccess.curator.ignoredShape": "Istniejąca wartość curatorRemote nie jest obsługiwaną wartością logiczną ani obiektem, więc wtyczka traktuje ją jako lokalną. Wybór trybu w tym miejscu zastępuje go.",
  "settings.varin.pluginSettings.webAccess.curator.remoteBroadWarning": "Zdalny Curator jest wystawiony na wszystkich interfejsach przez zwykły HTTP. Jego token URL i wyselekcjonowana zawartość są widoczne w sieci; preferuj konkretny prywatny adres powiązania.",
  "settings.varin.pluginSettings.webAccess.curator.remoteWarning": "Zdalny Curator wykorzystuje zwykły HTTP i tajny token URL. Zachowaj prywatność URL i łącz się tylko z zaufaną siecią.",
  "settings.varin.pluginSettings.webAccess.curator.remoteDescription": "Tryb lokalny jest bezpieczny i domyślny. Zdalny tryb pochodny używa nazwy hosta komputera i wiąże 0.0.0.0; tryb niestandardowy pozwala wybrać obie wartości.",
  "settings.varin.pluginSettings.webAccess.curator.mode.local": "Tylko lokalnie · 127.0.0.1",
